import{_ as r,a0 as p,w as l,s,ao as u,I as i,x as t,a1 as n,A as o}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const C=JSON.parse('{"title":"Linux用户，你們真的瞭解開源硬件嗎？ | LCTT x X-CMD","titleTemplate":false,"description":"Linux用户，你們真的瞭解開源硬件嗎？ | LCTT (201501) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Linux用户，你們真的瞭解開源硬件嗎？ | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Linux用户，你們真的瞭解開源硬件嗎？ | LCTT (201501) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201501/20140929 What Linux Users Should Know About Open Hardware","title":"Linux用户，你們真的瞭解開源硬件嗎？","tag":"201501","desc":""},"relativePath":"201501/20140929 What Linux Users Should Know About Open Hardware.md","filePath":"[post].md"}'),d={name:"201501/20140929 What Linux Users Should Know About Open Hardware.md"};function h(m,a,x,f,L,w){const e=p("Link");return l(),s("div",null,[a[13]||(a[13]=u('<h1 id="linux用户-你們真的瞭解開源硬件嗎" tabindex="-1">Linux用户，你們真的瞭解開源硬件嗎？ <a class="header-anchor" href="#linux用户-你們真的瞭解開源硬件嗎" aria-label="Permalink to “Linux用户，你們真的瞭解開源硬件嗎？”">​</a></h1><blockquote><p>Linux用户不瞭解一點開源硬件製造相關的事情，他們就會經常陷入失望的情緒中。</p></blockquote><p>商業軟件和免費軟件已經互相糾纏很多年了，但是這倆經常誤解對方。這並不奇怪 -- 對一方來説是生意，而另一方只是一種生活方式。但是，這種誤解會給人帶來痛苦，這也是為什麼值得花精力去揭露這裏面的內幕。</p><p>一個逐漸普遍的現象：對開源硬件的不斷嘗試，不管是Canonical，Jolla，MakePlayLive，或者其他公司。無論是評論員或是終端用户，通常免費軟件用户都會為新的硬件平台發佈表現出過分的狂熱，然後因為不斷延期有所醒悟，直到最終放棄整個產品。</p><p>這是一個沒有人獲益的怪圈，而且常常滋生出不信任 - 都是因為一般的Linux用户根本不知道這些新聞背後發生的事情。</p><p>我個人對於把產品推向市場的經驗很有限。但是，我還沒聽説誰能有所突破。推出一個開源硬件或其他產品到市場仍然不僅僅是個殘酷的生意，而且嚴重不利於新進廠商。</p><h3 id="尋找合作伙伴" tabindex="-1">尋找合作伙伴 <a class="header-anchor" href="#尋找合作伙伴" aria-label="Permalink to “尋找合作伙伴”">​</a></h3><p>不管是數碼產品的生產還是分銷都被相對較少的一些公司控制着，有時需要數月的預訂。利潤率也會很低，所以就像那些購買古老情景喜劇的電影工作室一樣，生產商一般也希望複製當前熱銷產品的成功。像Aaron Seigo在談到他花精力開發Vivaldi平板時告訴我的，生產商更希望能由其他人去承擔開發新產品的風險。</p><p>不僅如此，他們更希望和那些有現成銷售記錄的有可能帶來長期客户生意的人合作。</p><p>而且，一般新加入的廠商所關心的產品只有幾千的量。芯片製造商更願意和蘋果或三星這樣的公司合作，因為它們的訂單很可能是幾十上百萬的量。</p><p>面對這種情形，開源硬件製造者們可能會發現他們在工廠的列表中被淹沒了，除非能找到二線或三線廠願意嘗試一下小批量生產新產品。</p><p>他們也許還會淪為採購成品組件再自己組裝，就像Seigo嘗試Vivaldi時那樣做的。或者，他們也許可以像Canonical那樣做，尋找一些願意為這個產業冒險的合作伙伴。而就算他們成功了，一般也會比最初天真的預期延遲數個月。</p><h3 id="磕磕碰碰走向市場" tabindex="-1">磕磕碰碰走向市場 <a class="header-anchor" href="#磕磕碰碰走向市場" aria-label="Permalink to “磕磕碰碰走向市場”">​</a></h3><p>然而，尋找生產商只是第一關。根據樹莓派項目的經驗，就算開源硬件製造者們只想在他們的產品上運行免費軟件，生產商們很可能會以保護商業機密的名義堅持使用專有固件或驅動。</p><p>這樣必然會引起潛在用户的批評，但是開源硬件製造者沒得選，只能折中他們的願景。尋找其他生產商也不能解決問題，有一個原因是這樣做意味着更多延遲，但是更多的是因為完全免授權費的硬件是不存在的。像三星這樣的業內巨頭對免費硬件沒有任何興趣，而作為新人，開源硬件製造者也沒有影響力去要求什麼。</p><p>更何況，就算有免費硬件，生產商也不能保證會用在下一批生產中。製造者們會輕易地發現他們每次需要生產的時候都要重打一次一模一樣的仗。</p><p>這些都還不夠，這個時候開源硬件製造者們也許已經花了6-12個月時間來討價還價。等機會終於來了，產業標準卻已經變更，於是他們可能為了升級產品規格又要從頭來過。</p><h3 id="短暫而且殘忍的貨架期" tabindex="-1">短暫而且殘忍的貨架期 <a class="header-anchor" href="#短暫而且殘忍的貨架期" aria-label="Permalink to “短暫而且殘忍的貨架期”">​</a></h3><p>儘管面對這麼多困難，一定程度上開放的硬件也終於推出了。還記得尋找生產商時的挑戰嗎？對於分銷商也會有同樣的問題 -- 還不只是一次，而是每個地區都要解決。</p><p>通常，分銷商和生成商一樣保守，對於和新人或新點子打交道也很謹慎。就算他們同意一個產品上架，他們也輕易能夠決定不鼓勵自己的銷售代表們做推廣，這意味着這個產品會在幾個月後很有效率地下架。</p><p>當然，在線銷售也是可以的。但是同時，硬件還是需要被存放在某個地方，這也會增加成本。而按需生產就算可能的話也將非常昂貴，而且沒有組裝的元件也需要存放。</p><h3 id="衡量整件怪事" tabindex="-1">衡量整件怪事 <a class="header-anchor" href="#衡量整件怪事" aria-label="Permalink to “衡量整件怪事”">​</a></h3><p>在這裏我只是粗略地概括了一下，但是任何涉足過製造的人會認同我形容為行業標準的東西。而更糟糕的是，開源硬件製造者們通常只有在親身經歷過後才會有所覺悟。不可避免，他們也會犯錯，從而帶來更多的延遲。</p><p>但重點是，一旦你對整個過程有所瞭解，你對另一個開源硬件進行嘗試的新聞的反應就會改變。這個過程意味着，除非哪家公司處於嚴格的保密模式，對於產品將於六個月內發佈的聲明會很快會被證實是過期的推測。很可能是12-18個月，而且面對之前提過的那些困難很可能意味着這個產品永遠都不會真正發佈。</p><p>舉個例子，就像我寫的，人們等待第一代Steam Machines面世，它是一台基於Linux的遊戲主機。他們相信Steam Machines能徹底改變Linux和遊戲。</p><p>作為一個市場分類，Steam Machines也許比其他新產品更有優勢，因為參與開發的人員至少有開發軟件產品的經驗。然而，整整一年過去了Steam Machines的開發成果都還只有原型機，而且直到2015年中都不一定能買到。面對硬件生產的實際情況，就算有一半能見到陽光都是很幸運了。而實際上，能發佈2-4台也許更實際。</p><p>我做出這個預測並沒有考慮個體努力。但是，對硬件生產的理解，比起那些Linux和遊戲的黃金年代之類的預言，我估計這個更靠譜。如果我錯了也會很開心，但是事實不會改變：讓人吃驚的不是如此多的Linux相關硬件產品失敗了，而是那些雖然短暫但卻成功的產品。</p><hr>',28)),i("p",null,[a[1]||(a[1]=t("via: ",-1)),n(e,{href:"http://www.datamation.com/open-source/what-linux-users-should-know-about-open-hardware-1.html"},{default:o(()=>[...a[0]||(a[0]=[t("http://www.datamation.com/open-source/what-linux-users-should-know-about-open-hardware-1.html",-1)])]),_:1})]),i("p",null,[a[5]||(a[5]=t("作者：",-1)),n(e,{href:"http://www.datamation.com/author/Bruce-Byfield-6030.html"},{default:o(()=>[...a[2]||(a[2]=[t("Bruce Byfield",-1)])]),_:1}),a[6]||(a[6]=t(" 譯者：",-1)),n(e,{href:"https://github.com/zpl1025"},{default:o(()=>[...a[3]||(a[3]=[t("zpl1025",-1)])]),_:1}),a[7]||(a[7]=t(" 校對：",-1)),n(e,{href:"https://github.com/tinyeyeser"},{default:o(()=>[...a[4]||(a[4]=[t("Mr小眼兒",-1)])]),_:1})]),i("p",null,[a[10]||(a[10]=t("本文由 ",-1)),n(e,{href:"https://github.com/LCTT/TranslateProject"},{default:o(()=>[...a[8]||(a[8]=[t("LCTT",-1)])]),_:1}),a[11]||(a[11]=t(" 原創翻譯，",-1)),n(e,{href:"http://linux.cn/"},{default:o(()=>[...a[9]||(a[9]=[t("Linux中國",-1)])]),_:1}),a[12]||(a[12]=t(" 榮譽推出",-1))])])}const S=r(d,[["render",h]]);export{C as __pageData,S as default};
